// Formata o erro de qualquer workflow num alerta pro Thiago.
// Rajadas viram UM alerta agrupado: todo erro entra em giulia_erros_log;
// o aviso (dedup de 30 min por workflow) informa o total da meia hora.
// Erro de TRIGGER (ex.: conexao IMAP do WF18 caindo) chega SEM 'execution' -
// vem em j.trigger.error: registra a causa real e NAO acorda o Thiago por isso.
const j = items[0].json || {};
const wfName = (j.workflow && j.workflow.name) || 'workflow desconhecido';
const trig = (!j.execution && j.trigger) ? j.trigger : null;
const trigErr = (trig && trig.error) || {};
const execId = (j.execution && j.execution.id) || (trig ? 'trigger' : '?');
const node = (j.execution && (j.execution.lastNodeExecuted ||
  (j.execution.error && j.execution.error.node && j.execution.error.node.name))) ||
  (trig ? ('trigger(' + (trig.mode || 'ativo') + ')') : '?');
const msg = String((j.execution && j.execution.error && j.execution.error.message) ||
  trigErr.message || trigErr.description || (trig ? 'erro no trigger sem mensagem' : 'erro desconhecido'))
  .substring(0, 200).replace(/'/g, '');
const esc = s => String(s).replace(/'/g, "''");
const wfLike = esc(wfName).replace(/[%_]/g, '');
// reconexao do trigger de e-mail: so log, sem alerta no WhatsApp
const silencioso = !!trig && /email/i.test(wfName);
let sql =
  "SELECT pg_advisory_xact_lock(hashtext('alerta_" + esc(wfName) + "'));\n" +   // serializa handlers concorrentes (evita alerta duplicado)
  "INSERT INTO giulia_erros_log (workflow, node, mensagem) VALUES ('" + esc(wfName) + "', '" + esc(node) + "', '" + esc(msg) + "');\n";
if (!silencioso) sql +=
  "INSERT INTO giulia_mensagens_agendadas (destinatario_numero, destinatario_nome, conteudo, agendado_para, status) " +
  "SELECT '5511910441709', 'Thiago', " +
  "'⚠️ ' || (SELECT count(*) FROM giulia_erros_log WHERE workflow = '" + esc(wfName) + "' AND criado_em > NOW() - INTERVAL '30 minutes')::text || " +
  "' erro(s) no " + esc(wfName) + " na ultima meia hora. Ultimo (node " + esc(node) + "): " + esc(msg) + ". Exec " + esc(execId) + ". Se seguir aparecendo, olha o servidor.', " +
  "NOW() AT TIME ZONE 'America/Sao_Paulo', 'pendente' " +
  "WHERE NOT EXISTS (SELECT 1 FROM giulia_mensagens_agendadas WHERE destinatario_numero = '5511910441709' " +
  "AND conteudo LIKE '⚠️%erro(s) no " + wfLike + "%' AND criado_em > NOW() - INTERVAL '30 minutes');";
return [{ json: { sql, alerta: wfName + ': ' + msg, silencioso } }];
